import React, { useState, useEffect, useRef } from "react";
import * as d3 from "d3";
import { COLORS } from "../../utils/colors";
import { MO_PROVINCES, CANDIDATE_GEOJSON_URLS } from "../../utils/data";
import { priceColor, findProvinceName, matchProvince } from "../../utils/helpers";

export default function ChoroplethMap({ provinces }) {
  const list = provinces && provinces.length ? provinces : MO_PROVINCES;
  const [geo, setGeo] = useState(null);
  const [status, setStatus] = useState("loading");
  const ref = useRef(null);

  useEffect(() => {
    let cancelled = false;
    (async () => {
      for (const url of CANDIDATE_GEOJSON_URLS) {
        try {
          const res = await fetch(url);
          if (!res.ok) continue;
          const json = await res.json();
          const features = json.type === "Topology" ? null : json.features;
          if (features && features.length && !cancelled) {
            setGeo(json);
            setStatus("ok");
            return;
          }
        } catch (e) {
          continue;
        }
      }
      if (!cancelled) setStatus("fallback");
    })();
    return () => { cancelled = true; };
  }, []);

  if (status === "loading") {
    return (
      <div style={{ height: 340, display: "flex", alignItems: "center", justifyContent: "center", fontFamily: "Sarabun, sans-serif", fontSize: 13, color: COLORS.sub }}>
        Loading province boundaries&hellip;
      </div>
    );
  }

  if (status === "fallback") {
    const fallbackPos = {
      Bulacan: [60, 72], Pampanga: [44, 55], "Nueva Ecija": [66, 36],
      Tarlac: [44, 20], Bataan: [20, 66], Zambales: [15, 30], Aurora: [86, 30]
    };
    return (
      <div style={{ position: "relative", width: "100%", height: 340, background: "#EAF3FC", borderRadius: 10 }}>
        <svg viewBox="0 0 100 90" style={{ width: "100%", height: "100%" }} role="img" aria-label="Schematic map of Region III provinces colored by retail price">
          {list.map(p => {
            const [x, y] = fallbackPos[p.name];
            return (
              <g key={p.name}>
                <circle cx={x} cy={y} r={6} fill={priceColor(p.price)} />
                <text x={x} y={y - 9} textAnchor="middle" fontSize="4" fontFamily="Sarabun" fill={COLORS.ink} fontWeight="600">{p.name}</text>
              </g>
            );
          })}
        </svg>
        <div style={{ position: "absolute", bottom: 8, left: 10, fontFamily: "Sarabun, sans-serif", fontSize: 10.5, color: COLORS.sub }}>
          Geometry service unavailable &mdash; showing schematic positions.
        </div>
      </div>
    );
  }

  const path = d3.geoPath(d3.geoMercator().fitSize([100, 90], geo));
  return (
    <svg viewBox="0 0 100 90" ref={ref} style={{ width: "100%", height: 340, background: "#EAF3FC", borderRadius: 10 }} role="img" aria-label="Choropleth map of Region III provinces colored by retail price">
      {geo.features.map((f, i) => {
        const match = matchProvince(findProvinceName(f.properties), list);
        return (
          <path
            key={i}
            d={path(f)}
            fill={match ? priceColor(match.price) : "#DCE7F5"}
            stroke="#FFFFFF"
            strokeWidth={0.3}
          >
            {match && <title>{`${match.name}: ₱${match.price.toFixed(2)}/kg`}</title>}
          </path>
        );
      })}
    </svg>
  );
}
